+            using HttpListener listener = new();
+            Task response = Task.CompletedTask;
+            if (status != "connection-unavailable")
+            {
+                listener.Prefixes.Add($"http://127.0.0.1:{plan.Ports.EventStoreDaprHttp}/");
+                listener.Start();
+                response = Task.Run(
+                    async () =>
